-- Name: amazon_products; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.amazon_products (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_name text NOT NULL,
    asin text,
    category text NOT NULL,
    price_inr numeric NOT NULL,
    rating numeric(2,1),
    reviews_count integer,
    description text,
    features jsonb,
    reviews jsonb,
    specifications jsonb,
    image_url text,
    product_url text,
    availability_status text DEFAULT 'in_stock'::text NOT NULL,
    last_updated timestamp without time zone DEFAULT now() NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    is_deleted boolean DEFAULT false NOT NULL,
    brand text,
    affiliate_url text,
    recommendations jsonb,
    price_comparisons jsonb,
    review_score numeric(5,4) DEFAULT 0,
    brand_score numeric(3,2) DEFAULT 0.5,
    feature_score numeric(3,2) DEFAULT 0,
    median_price_category numeric(10,2) DEFAULT 0,
    has_anc boolean DEFAULT false,
    battery_hours integer DEFAULT 0,
    has_fast_charge boolean DEFAULT false,
    mic_quality_score numeric(3,2) DEFAULT 0.5,
    has_app_support boolean DEFAULT false,
    color character varying(50),
    design_style character varying(50),
    detected_category boolean DEFAULT false,
    classified_tag text,
    CONSTRAINT amazon_products_availability_status_check CHECK ((availability_status = ANY (ARRAY['in_stock'::text, 'out_of_stock'::text, 'archived'::text]))),
    CONSTRAINT amazon_products_category_check CHECK ((category = ANY (ARRAY['headphones'::text, 'earbuds'::text, 'neckbands'::text, 'wired_earphones'::text, 'robot_vacuums'::text]))),
    CONSTRAINT amazon_products_price_inr_check CHECK ((price_inr >= (0)::numeric)),
    CONSTRAINT amazon_products_rating_check CHECK (((rating >= 0.0) AND (rating <= 5.0)))
);


